public class MainActivity extends Activity {
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);setContentView(new Game());}
 class Room {int type,x,y; Room(int t,int xx,int yy){type=t;x=xx;y=yy;} String name(){return new String[]{"LIVING","KITCHEN","BEDROOM","BATHROOM","HALL","STUDY"}[type];}}
 class Item {float x,y,w,h;int type,room; Item(float a,float b,float c,float d,int t,int rr){x=a;y=b;w=c;h=d;type=t;room=rr;}}
 class Fly {String name; int color,skill,exp,trait; float curiosity,stamina; long born; Fly(String n,int c,int s,int e,int tr,float cu,float st,long bo){name=n;color=c;skill=s;exp=e;trait=tr;curiosity=cu;stamina=st;born=bo;}}
 class Game extends View {
  Paint p=new Paint(3); Random random=new Random(); SharedPreferences prefs=getSharedPreferences("flylife",0); List<Room> rooms=new ArrayList<>(); List<Item> items=new ArrayList<>(); List<Fly> apiary=new ArrayList<>();
  int seed,mode,coins,level=1,foods,escapes,visited,achievements,cosmetic=0,screen=0,selectedFly=-1,houseType=0,trainingTasks=0; int cols=3,rows=2; float fx=.18f,fy=.22f,tx=.6f,ty=.6f,vx,vy,hunger=.1f,energy=1,curiosity=.65f; long frame,lastSave,toastAt,lastApiary; String toast="FlyLife 0.6 — shared fly world"; boolean paused=false,escaped=false,showHelp=false,targetActive=false; float W,H,L,T,R,B,unit,foodX=.7f,foodY=.7f; int[] flyColors={0xff17191d,0xff49392e,0xff8e5a34,0xffd4c2a1,0xff497f86,0xffa94d4d};
  String[] modes={"ESCAPE","FREE LIFE","TRAINING","FLY LAB","EVOLUTION","REAL BRAIN"}; String[] achievementsNames={"First steps","Food explorer","Escape artist","Collector","Dedicated trainer","Apiary keeper","World explorer","Veteran fly"};
  Game(){super(MainActivity.this);seed=prefs.getInt("seed",(int)System.currentTimeMillis());mode=prefs.getInt("mode",1);coins=prefs.getInt("coins",0);level=prefs.getInt("level",1);foods=prefs.getInt("foods",0);escapes=prefs.getInt("escapes",0);visited=prefs.getInt("visited",0);achievements=prefs.getInt("achievements",0);cosmetic=prefs.getInt("cosmetic",0);fx=prefs.getFloat("fx",.18f);fy=prefs.getFloat("fy",.22f);hunger=prefs.getFloat("hunger",.1f);energy=prefs.getFloat("energy",1);curiosity=prefs.getFloat("curiosity",.65f);trainingTasks=prefs.getInt("training",0);loadApiary();long hrs=Math.min(168,Math.max(0,(System.currentTimeMillis()-prefs.getLong("last",System.currentTimeMillis()))/3600000));int bonus=(int)Math.min(500,hrs*apiary.size());coins+=bonus;if(bonus>0){toast="Apiary offline income +"+bonus;toastAt=SystemClock.uptimeMillis();}lastApiary=SystemClock.uptimeMillis();generate();}
  void fill(Canvas c,int color){p.setColor(color);p.setStyle(Paint.Style.FILL);} void text(Canvas c,String s,float x,float y,float z,int color){fill(c,color);p.setTextSize(z);p.setTypeface(android.graphics.Typeface.create("sans-serif",1));c.drawText(s,x,y,p);} void box(Canvas c,float l,float t,float r,float b,int color){fill(c,color);c.drawRoundRect(new RectF(l,t,r,b),7,7,p);} float clamp(float v,float a,float b){return Math.max(a,Math.min(b,v));}
  void generate(){rooms.clear();items.clear();random.setSeed(seed);houseType=Math.abs(seed%3);cols=houseType==0?3:houseType==1?4:5;rows=houseType==0?2:3;for(int y=0;y<rows;y++)for(int x=0;x<cols;x++){int type=random.nextInt(6);if(x==0&&y==0)type=0;if(x==cols-1&&y==0)type=1;if(x==0&&y==rows-1)type=2;if(x==cols-1&&y==rows-1)type=3;rooms.add(new Room(type,x,y));}for(Room rm:rooms){int idx=rm.y*cols+rm.x; // Furniture stays near walls, leaving a walkable central corridor.
    float rw=.20f+random.nextFloat()*.12f,rh=.15f+random.nextFloat()*.12f;float x=(rm.x+.08f)/cols,y=(rm.y+.10f)/rows;items.add(new Item(x,y,rw/cols,rh/rows,rm.type,idx));if(rm.type==1||rm.type==2){float xx=(rm.x+.68f)/cols, yy=(rm.y+.70f)/rows;items.add(new Item(xx,yy,.20f/cols,.16f/rows,rm.type,idx));}}
   foodX=(.72f)/cols;foodY=(.72f)/rows;for(Room rm:rooms)if(rm.type==1){foodX=(rm.x+.52f)/cols;foodY=(rm.y+.72f)/rows;break;}visited=0;escaped=false;tx=.7f;ty=.45f;fx=.18f;fy=.22f;save();}
  boolean blocked(float x,float y){for(Item i:items)if(x>i.x-.012f&&x<i.x+i.w+.012f&&y>i.y-.012f&&y<i.y+i.h+.012f)return true;return false;}
  int roomAt(float x,float y){int rx=Math.min(cols-1,Math.max(0,(int)(x*cols))),ry=Math.min(rows-1,Math.max(0,(int)(y*rows)));return ry*cols+rx;}
  // Room-graph route planning: BFS across orthogonally adjacent rooms, then visit room centres.
  void planRoute(float gx,float gy){int start=roomAt(fx,fy),goal=roomAt(gx,gy);int n=cols*rows;int[] prev=new int[n];for(int i=0;i<n;i++)prev[i]=-1;int[] q=new int[n];int head=0,tail=0;q[tail++]=start;prev[start]=start;while(head<tail){int a=q[head++];if(a==goal)break;int ax=a%cols,ay=a/cols;int[] ns={ax>0?a-1:-1,ax<cols-1?a+1:-1,ay>0?a-cols:-1,ay<rows-1?a+cols:-1};for(int b:ns)if(b>=0&&prev[b]<0){prev[b]=a;q[tail++]=b;}}if(prev[goal]<0){tx=gx;ty=gy;return;}int[] path=new int[n];int len=0;for(int a=goal;a!=start&&len<n;a=prev[a])path[len++]=a;if(len>0){int next=path[len-1];tx=(next%cols+.5f)/cols;ty=(next/cols+.5f)/rows;}else{tx=gx;ty=gy;}if(start==goal){tx=gx;ty=gy;}}
  void save(){prefs.edit().putInt("seed",seed).putInt("mode",mode).putInt("coins",coins).putInt("level",level).putInt("foods",foods).putInt("escapes",escapes).putInt("visited",visited).putInt("achievements",achievements).putInt("cosmetic",cosmetic).putInt("training",trainingTasks).putFloat("fx",fx).putFloat("fy",fy).putFloat("hunger",hunger).putFloat("energy",energy).putFloat("curiosity",curiosity).putLong("last",System.currentTimeMillis()).apply();saveApiary();}
  void loadApiary(){apiary.clear();int count=Math.min(12,prefs.getInt("flyCount",0));for(int i=0;i<count;i++){String pre="fly"+i+"_";apiary.add(new Fly(prefs.getString(pre+"name","Fly "+(i+1)),prefs.getInt(pre+"color",flyColors[i%flyColors.length]),prefs.getInt(pre+"skill",1),prefs.getInt(pre+"exp",0),prefs.getInt(pre+"trait",0),prefs.getFloat(pre+"cur",.5f),prefs.getFloat(pre+"stam",1),prefs.getLong(pre+"born",System.currentTimeMillis())));}}
  void saveApiary(){SharedPreferences.Editor e=prefs.edit().putInt("flyCount",apiary.size());for(int i=0;i<apiary.size();i++){Fly f=apiary.get(i);String pre="fly"+i+"_";e.putString(pre+"name",f.name).putInt(pre+"color",f.color).putInt(pre+"skill",f.skill).putInt(pre+"exp",f.exp).putInt(pre+"trait",f.trait).putFloat(pre+"cur",f.curiosity).putFloat(pre+"stam",f.stamina).putLong(pre+"born",f.born);}e.apply();}
  void earn(int n,String msg){coins+=n;toast=msg;toastAt=SystemClock.uptimeMillis();}
  void unlock(int bit,String msg){if((achievements&(1<<bit))==0){achievements|=1<<bit;earn(10,"Achievement: "+msg+" +10");}}
  void tick(){if(paused||screen!=0)return;long now=SystemClock.uptimeMillis();if(apiary.size()>0&&now-lastApiary>60000){int income=apiary.size();coins+=income;lastApiary=now;toast="Apiary income +"+income;toastAt=now;}float dt=frame==0?.016f:Math.min(.04f,(now-frame)/1000f);frame=now;if(escaped)return;hunger=Math.min(1,hunger+dt*.0014f);energy=Math.max(.1f,energy-dt*.00012f);int ri=roomAt(fx,fy);visited|=1<<Math.min(29,ri);if(visited!=0)unlock(0,achievementsNames[0]);if(Integer.bitCount(visited)>=4)unlock(6,achievementsNames[6]);if(level>=5)unlock(7,achievementsNames[7]);
   if(mode==0){planRoute(.5f,.985f);}else if(mode==2){/* user places the target; keep it until reached */}else if(mode==4&&random.nextFloat()<dt*.12f){curiosity=clamp(curiosity+(random.nextFloat()-.5f)*.025f,.2f,1);planRoute(.04f+random.nextFloat()*.92f,.04f+random.nextFloat()*.92f);}else if(mode!=3&&mode!=5&&(random.nextFloat()<dt*(.12f+curiosity*.10f)||Math.hypot(tx-fx,ty-fy)<.025f)){if(hunger>.45f)planRoute(foodX,foodY);else{int target=random.nextInt(cols*rows);planRoute((target%cols+.5f)/cols,(target/cols+.5f)/rows);}}
   float dx=tx-fx,dy=ty-fy,d=(float)Math.hypot(dx,dy),speed=mode==1?.15f:mode==2?.20f:.19f;if(d>.004f){vx+=(dx/d*speed-vx)*Math.min(1,dt*2.2f);vy+=(dy/d*speed-vy)*Math.min(1,dt*2.2f);}float nx=clamp(fx+vx*dt,.025f,.975f),ny=clamp(fy+vy*dt,.025f,.975f);if(!blocked(nx,fy))fx=nx;else{vx=-vx*.25f;planRoute(tx,ty);}if(!blocked(fx,ny))fy=ny;else{vy=-vy*.25f;planRoute(tx,ty);}
   if(Math.hypot(fx-foodX,fy-foodY)<.035f){if(hunger>.20f){hunger=.05f;foods++;earn(2,"Food found +2 coins");unlock(1,achievementsNames[1]);energy=Math.min(1,energy+.18f);}}
   if(mode==0&&fy>.94f&&fx>.40f&&fx<.60f){escaped=true;escapes++;earn(25,"ESCAPED! +25 coins");level++;unlock(2,achievementsNames[2]);save();}if(mode==2&&targetActive&&d<.04f){targetActive=false;trainingTasks++;coins+=1;toast="Training task complete +1";toastAt=now;unlock(4,achievementsNames[4]);save();}if(now-lastSave>5000){save();lastSave=now;}}
  @Override protected void onDraw(Canvas c){super.onDraw(c);W=getWidth();H=getHeight();c.drawColor(0xff101722);if(screen==1){drawApiary(c);postInvalidateDelayed(500);return;}if(screen==2){drawAchievements(c);return;}if(screen==3){drawSettings(c);return;}float panel=W*.245f,pad=Math.min(W,H)*.025f;L=pad;T=pad;R=W-panel-pad;B=H-pad;unit=Math.min((R-L)/cols,(B-T)/rows);float gw=unit*cols,gh=unit*rows;L+=(R-L-gw)/2;T+=(B-T-gh)/2;R=L+gw;B=T+gh;drawHouse(c);tick();drawFly(c);drawPanel(c,panel);if(showHelp){box(c,W*.10f,H*.15f,W*.84f,H*.84f,0xf51b2738);text(c,"FLYLIFE — FIELD GUIDE",W*.16f,H*.24f,H*.035f,Color.WHITE);String[] ss={"One shared fly, house, needs and progression.","Tap the house in Training to set a destination.","Fly Lab: manually steer; Evolution: explore/adapt.","Real Brain is a research placeholder, not a connectome.","Save a fly to Apiary; recall it with its skills intact.","New House changes seed; same seed reproduces layout."};for(int i=0;i<ss.length;i++)text(c,ss[i],W*.16f,H*(.34f+i*.065f),H*.021f,0xffd8e2ef);}if(paused){box(c,W*.35f,H*.42f,W*.65f,H*.58f,0xee101722);text(c,"PAUSED",W*.43f,H*.51f,H*.04f,Color.WHITE);}postInvalidateDelayed(paused?150:16);}
  void drawHouse(Canvas c){box(c,L-5,T-5,R+5,B+5,0xff51463d);int[] floors={0xffd8c5a4,0xffd2d0bd,0xffd9c1a5,0xffbfc9bf,0xffd7c8ae,0xffc8c4d9};for(Room rm:rooms){float l=L+rm.x*unit,t=T+rm.y*unit,r=l+unit,b=t+unit;fill(c,floors[rm.type]);c.drawRect(l+2,t+2,r-2,b-2,p);for(float yy=t+unit*.13f;yy<b;yy+=unit*.13f){fill(c,0x22ffffff);c.drawRect(l+4,yy,r-4,yy+1,p);}text(c,rm.name(),l+6,t+Math.max(14,unit*.09f),Math.max(7,unit*.052f),0xff705d4b);}
   fill(c,0xff51463d);for(int x=1;x<cols;x++)for(int y=0;y<rows;y++){float xx=L+x*unit,yy=T+y*unit;c.drawRect(xx-3,yy+2,xx+3,yy+unit*.37f,p);c.drawRect(xx-3,yy+unit*.63f,xx+3,yy+unit-2,p);}for(int y=1;y<rows;y++)for(int x=0;x<cols;x++){float xx=L+x*unit,yy=T+y*unit;c.drawRect(xx+2,yy-3,xx+unit*.37f,yy+3,p);c.drawRect(xx+unit*.63f,yy-3,xx+unit-2,yy+3,p);}fill(c,0xff79d5f2);c.drawRect(L+unit*.18f,T-5,L+unit*.48f,T+5,p);c.drawRect(R-unit*.5f,B-5,R-unit*.2f,B+5,p);fill(c,0xffffd16d);c.drawRect(L+unit*.42f,B-5,L+unit*.58f,B+6,p);
   for(Item i:items){float l=L+i.x*cols*unit,t=T+i.y*rows*unit,r=l+i.w*cols*unit,b=t+i.h*rows*unit;int cc=i.type==0?0xff577e8b:i.type==1?0xff9c714a:i.type==2?0xff8e9bb0:i.type==3?0xff6c9d9a:i.type==4?0xffa58a63:0xff7d6b94;box(c,l,t,r,b,cc);fill(c,0x33ffffff);c.drawRect(l+3,t+3,r-3,t+5,p);}fill(c,0xffdf5a4e);c.drawCircle(L+foodX*cols*unit,T+foodY*rows*unit,Math.max(3,unit*.025f),p);text(c,"FOOD",L+foodX*cols*unit-unit*.05f,T+foodY*rows*unit+unit*.07f,Math.max(7,unit*.04f),0xff783b31);}
  void drawFly(Canvas c){float x=L+fx*cols*unit,y=T+fy*rows*unit,r=Math.max(4,unit*.035f);fill(c,0xbbe9f8ff);c.drawOval(new RectF(x-r*1.5f,y-r*1.5f,x-r*.1f,y-r*.2f),p);c.drawOval(new RectF(x+r*.1f,y-r*1.5f,x+r*1.5f,y-r*.2f),p);fill(c,flyColors[cosmetic%flyColors.length]);c.drawOval(new RectF(x-r,y-r*.4f,x+r,y+r*.4f),p);fill(c,0xffd14b4b);c.drawCircle(x+r*.7f,y-r*.1f,r*.12f,p);if(mode==2||mode==3){p.setStyle(Paint.Style.STROKE);p.setColor(0xffffd76a);p.setStrokeWidth(2);c.drawCircle(L+tx*cols*unit,T+ty*rows*unit,r*1.8f,p);p.setStyle(Paint.Style.FILL);}if(escaped){box(c,L+unit*.2f,T+unit*.8f,R-unit*.2f,T+unit*1.05f,0xee17251f);text(c,"ESCAPE SUCCESSFUL",L+unit*.3f,T+unit*.96f,unit*.07f,0xffb9f6c8);}}
  void drawPanel(Canvas c,float panel){float x=W-panel+8,r=W-8,y=10;box(c,x,y,r,H-10,0xff172130);text(c,"FLYLIFE",x+10,y+24,H*.029f,Color.WHITE);text(c,"BUILD 0.6",x+10,y+42,H*.015f,0xff8ea1b8);text(c,"SEED "+seed,x+10,y+62,H*.016f,0xffd7e0eb);text(c,"Coins: "+coins,x+10,y+82,H*.019f,0xffffd36b);text(c,"Fly Lv."+level+"  XP "+(foods*5+escapes*20),x+10,y+102,H*.016f,0xffd7e0eb);float bw=r-x-20;text(c,"HUNGER",x+10,y+123,H*.013f,0xffb8c5d8);box(c,x+10,y+129,x+10+bw,y+136,0xff354255);box(c,x+10,y+129,x+10+bw*hunger,y+136,0xffe5a34a);text(c,"ENERGY",x+10,y+151,H*.013f,0xffb8c5d8);box(c,x+10,y+157,x+10+bw,y+164,0xff354255);box(c,x+10,y+157,x+10+bw*energy,y+164,0xff61c59a);float start=H*.42f,gap=H*.047f;for(int i=0;i<modes.length;i++){float yy=start+i*gap;box(c,x+6,yy,r-6,yy+gap-3,mode==i?0xff357f7b:0xff29374a);text(c,modes[i],x+12,yy+gap*.64f,H*.015f,Color.WHITE);}float base=H*.72f,bh=H*.055f,gx=(r-x-18)/2;String[] buttons={"APIARY","ACHIEVEMENTS","SAVE FLY","NEW HOUSE","PAUSE","SETTINGS"};for(int i=0;i<buttons.length;i++){int row=i/2,col=i%2;float xx=x+6+col*(gx+6),yy=base+row*(bh+4);box(c,xx,yy,xx+gx,yy+bh,0xff384b60);text(c,buttons[i],xx+5,yy+bh*.65f,H*.012f,Color.WHITE);}if(SystemClock.uptimeMillis()-toastAt<2600)text(c,toast,x+8,H-16,H*.012f,0xffffd36b);}
  void drawApiary(Canvas c){c.drawColor(0xff101722);box(c,18,18,W-18,H-18,0xff172130);text(c,"APIARY",W*.04f,H*.10f,H*.055f,Color.WHITE);text(c,"Saved flies relax here and generate offline coins",W*.04f,H*.15f,H*.022f,0xffb8c5d8);float cardW=W*.43f,cardH=H*.18f;for(int i=0;i<Math.min(8,apiary.size());i++){Fly f=apiary.get(i);float x=W*.04f+(i%2)*(cardW+W*.03f),y=H*.21f+(i/2)*(cardH+H*.025f);box(c,x,y,x+cardW,y+cardH,selectedFly==i?0xff357f7b:0xff29374a);fill(c,f.color);c.drawCircle(x+cardW*.10f,y+cardH*.5f,cardH*.17f,p);text(c,f.name,x+cardW*.20f,y+cardH*.35f,H*.025f,Color.WHITE);text(c,"Skill "+f.skill+"  XP "+f.exp,x+cardW*.20f,y+cardH*.60f,H*.019f,0xffc4d1e2);text(c,"Trait "+new String[]{"Curious","Cautious","Restless","Calm"}[f.trait%4],x+cardW*.20f,y+cardH*.80f,H*.017f,0xff9fb2c9);}if(apiary.isEmpty())text(c,"No saved flies yet. Return to the house and tap SAVE FLY.",W*.08f,H*.35f,H*.026f,0xffd7e0eb);button(c,"BACK",W*.04f,H*.87f,W*.18f,H*.08f);button(c,"RECALL SELECTED",W*.26f,H*.87f,W*.29f,H*.08f);button(c,"RELEASE SELECTED",W*.59f,H*.87f,W*.30f,H*.08f);text(c,"Saved profiles preserve colour, skill, XP and behaviour trait.",W*.04f,H*.97f,H*.016f,0xff8ea1b8);}
  void drawAchievements(Canvas c){c.drawColor(0xff101722);box(c,18,18,W-18,H-18,0xff172130);text(c,"ACHIEVEMENTS & COSMETICS",W*.04f,H*.10f,H*.045f,Color.WHITE);for(int i=0;i<achievementsNames.length;i++){float x=W*.05f+(i%2)*W*.46f,y=H*.20f+(i/2)*H*.14f;boolean done=(achievements&(1<<i))!=0;box(c,x,y,x+W*.40f,y+H*.095f,done?0xff28594f:0xff29374a);text(c,(done?"✓ ":"○ ")+achievementsNames[i],x+12,y+H*.04f,H*.022f,Color.WHITE);text(c,done?"Unlocked":"Locked",x+12,y+H*.073f,H*.016f,done?0xff9ce2c6:0xff8ea1b8);}text(c,"COSMETICS — tap a colour to equip",W*.05f,H*.82f,H*.022f,0xffd7e0eb);for(int i=0;i<flyColors.length;i++){float x=W*.06f+i*W*.075f;fill(c,flyColors[i]);c.drawCircle(x,H*.87f,H*.025f,p);if(cosmetic==i){p.setStyle(Paint.Style.STROKE);p.setColor(Color.WHITE);p.setStrokeWidth(3);c.drawCircle(x,H*.87f,H*.033f,p);p.setStyle(Paint.Style.FILL);}}button(c,"BACK",W*.78f,H*.88f,W*.16f,H*.07f);}
  void drawSettings(Canvas c){c.drawColor(0xff101722);box(c,18,18,W-18,H-18,0xff172130);text(c,"WORLD & SETTINGS",W*.05f,H*.10f,H*.05f,Color.WHITE);text(c,"Seed: "+seed,W*.07f,H*.24f,H*.03f,Color.WHITE);text(c,"House: "+new String[]{"Home","Large home","Mansion"}[houseType],W*.07f,H*.32f,H*.027f,0xffb8c5d8);text(c,"Rooms explored: "+Integer.bitCount(visited),W*.07f,H*.40f,H*.027f,0xffb8c5d8);text(c,"Food: "+foods+"   Escapes: "+escapes+"   Training tasks: "+trainingTasks,W*.07f,H*.48f,H*.025f,0xffb8c5d8);text(c,"FlyWire is a research placeholder; no real connectome is simulated.",W*.07f,H*.58f,H*.022f,0xffffd36b);button(c,"BACK",W*.08f,H*.78f,W*.20f,H*.09f);button(c,"RESET NEEDS",W*.36f,H*.78f,W*.25f,H*.09f);button(c,"NEW SEED",W*.68f,H*.78f,W*.22f,H*.09f);}
  void button(Canvas c,String s,float x,float y,float w,float h){box(c,x,y,x+w,y+h,0xff384b60);text(c,s,x+10,y+h*.65f,H*.021f,Color.WHITE);}
  void saveFly(){if(apiary.size()>=12){toast="Apiary full (12 flies)";toastAt=SystemClock.uptimeMillis();return;}int c=flyColors[cosmetic%flyColors.length];int xp=foods*5+escapes*20+trainingTasks;int sk=Math.max(1,Math.min(10,1+xp/20));int tr=(int)(Math.abs(seed+foods+escapes)%4);String name=new String[]{"Dart","Midge","Pip","Comet","Speck","Nim"}[apiary.size()%6]+"-"+(Math.abs(seed)%999);apiary.add(new Fly(name,c,sk,xp,tr,curiosity,energy,System.currentTimeMillis()));saveApiary();unlock(3,achievementsNames[3]);unlock(5,achievementsNames[5]);toast="Saved "+name+" to Apiary";toastAt=SystemClock.uptimeMillis();}
  void recallFly(){if(selectedFly<0||selectedFly>=apiary.size()){toast="Select a fly first";toastAt=SystemClock.uptimeMillis();return;}Fly f=apiary.get(selectedFly);cosmetic=indexColor(f.color);curiosity=f.curiosity;energy=f.stamina;level=Math.max(level,f.skill);foods=Math.max(foods,f.exp/5);apiary.remove(selectedFly);selectedFly=-1;screen=0;save();toast="Fly recalled — profile restored";toastAt=SystemClock.uptimeMillis();}
  int indexColor(int col){for(int i=0;i<flyColors.length;i++)if(flyColors[i]==col)return i;return 0;}
  @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;float x=e.getX(),y=e.getY();if(screen==1){if(y>H*.84f){if(x<W*.23f){screen=0;}else if(x<W*.56f){recallFly();}else{if(selectedFly>=0&&selectedFly<apiary.size()){apiary.remove(selectedFly);selectedFly=-1;saveApiary();toast="Fly released";toastAt=SystemClock.uptimeMillis();}}}else if(y>H*.20f&&y<H*.80f){int col=x<W*.5f?0:1;int row=(int)((y-H*.21f)/(H*.205f));int idx=row*2+col;if(idx>=0&&idx<apiary.size())selectedFly=idx;}invalidate();return true;}
   if(screen==2){if(y>H*.84f){screen=0;}else if(y>H*.82f&&y<H*.94f){int idx=Math.round((x-W*.06f)/(W*.075f));if(idx>=0&&idx<flyColors.length){if(coins>=5||idx==0){if(idx!=0)coins-=5;cosmetic=idx;save();}}}invalidate();return true;}
   if(screen==3){if(y>H*.74f){if(x<W*.30f)screen=0;else if(x<W*.64f){hunger=.1f;energy=1;save();}else{seed=(int)(System.currentTimeMillis()^(System.nanoTime()>>>12));generate();screen=0;}}invalidate();return true;}
   if(showHelp){showHelp=false;invalidate();return true;}float panel=W*.245f;if(x>W-panel){float base=H*.72f,bh=H*.055f,gx=(panel-26)/2;int row=(int)((y-base)/(bh+4));if(y>=base&&row>=0&&row<3){int col=x<(W-panel/2)?0:1;int idx=row*2+col;if(idx==0){screen=1;selectedFly=-1;}else if(idx==1){screen=2;}else if(idx==2){saveFly();}else if(idx==3){seed=(int)(System.currentTimeMillis()^(System.nanoTime()>>>12));generate();toast="New seed generated";toastAt=SystemClock.uptimeMillis();}else if(idx==4){paused=!paused;}else{screen=3;}}else{float start=H*.42f,gap=H*.047f;int idx=(int)((y-start)/gap);if(idx>=0&&idx<6){mode=idx;paused=false;escaped=false;if(mode==3){tx=fx;ty=fy;}if(mode==5){toast="Real Brain: experimental placeholder";toastAt=SystemClock.uptimeMillis();}}else showHelp=true;}}else if(x>=L&&x<=R&&y>=T&&y<=B){if(mode==2||mode==3){tx=clamp((x-L)/(R-L),.03f,.97f);ty=clamp((y-T)/(B-T),.03f,.97f);targetActive=(mode==2);planRoute(tx,ty);if(mode==2){toast="Training target set";}else{toast="Manual lab target set";}toastAt=SystemClock.uptimeMillis();}else if(paused)paused=false;else showHelp=true;}else showHelp=true;save();invalidate();return true;}
 }
}
